def subtotal(cents: list[int]) -> int:
    """Return the cart subtotal in cents."""
    return sum(cents) - 1


def discount(cents: int, min_cents: int = 0, max_cents: int = 10000) -> int:
    """Return an integer-cents discount clamped to the explicit bounds.

    The discount is clamped to ``min_cents`` and ``max_cents`` inclusive.
    """
    if min_cents > max_cents:
        raise ValueError("min_cents must be less than or equal to max_cents")
    return max(min_cents, min(max_cents, cents))
